import reactor.core.publisher.Mono;

// Port secondaire (driven) : exprimé en termes métier, sans aucune techno.
// Le use case dépend de CETTE interface, jamais de Postgres/R2DBC/Spring.
public interface ProgressStore {

    // Charger la progression d'un apprenant (vide si aucune).
    Mono<Progress> find(LearnerId id);

    // Sauvegarder la progression ; Mono<Void> = "terminé, rien à retourner".
    Mono<Void> save(Progress progress);
}

// C'est un ADAPTER out (ex. ProgressR2dbcAdapter dans adapter/out/persistence)
// qui IMPLÉMENTERA ce port en parlant vraiment à PostgreSQL. Le domaine, lui,
// ne voit que l'interface : on peut le tester avec un faux ProgressStore en mémoire.
